import re

from langflow.custom import Component
from langflow.io import HandleInput, MultilineInput, Output
from langflow.schema.message import Message


class CustomComponent(Component):
    display_name = "RAG Prompt Builder"
    description = "Ground the question in live quotes, fresh web results and retrieved news before the LLM answers."
    icon = "filter"
    name = "StockSageRagPrompt"

    MAX_ARTICLES = 6
    MAX_WEB = 5
    _IMPORTANCE = {"high": 0, "medium": 1, "low": 2}
    # Uppercase tokens that look like tickers but are not, so parsing a question
    # in the Playground (where the app's focus tweak is absent) stays sane.
    _NOT_TICKERS = {
        "AND", "OR", "THE", "VS", "AN", "TO", "IS", "IT", "OF", "ON", "IN",
        "BE", "DO", "US", "AI", "EV", "IPO", "CEO", "CFO", "ETF", "GDP",
        "WWDC", "USD", "EPS", "YOY", "SEC", "FED", "API", "ATH", "USA",
    }
    _STOP_WORDS = {
        "how", "hows", "whats", "what", "the", "versus", "and", "are", "doing",
        "about", "compared", "compare", "former", "latter", "now", "days",
        "stock", "stocks", "share", "shares", "price", "than", "with", "for",
        "this", "that", "these", "those", "you", "your", "give", "tell", "vs",
        "look", "looking", "today", "currently", "vs.", "between",
    }

    inputs = [
        HandleInput(
            name="question",
            display_name="Question",
            input_types=["Message"],
            info="The user's latest chat message (also the vector-search query).",
        ),
        HandleInput(
            name="context",
            display_name="Retrieved News",
            input_types=["Data", "DataFrame", "Table"],
            info="Vector-search results from the Astra DB news store.",
        ),
        HandleInput(
            name="web_results",
            display_name="Web Results",
            input_types=["Data", "DataFrame", "Table"],
            info="Live web-search results (Tavily) for up-to-date context on any entity.",
        ),
        MultilineInput(
            name="live_data",
            display_name="Live Market Data",
            info="Real-time price / percent change lines injected by the app.",
        ),
        MultilineInput(
            name="history",
            display_name="Conversation History",
            info="Recent turns so follow-up questions keep their subject.",
        ),
        MultilineInput(
            name="focus_tickers",
            display_name="Focus Tickers",
            info="Comma-separated tickers in scope; keeps retrieved news on-subject.",
        ),
    ]
    outputs = [Output(display_name="Prompt", name="prompt", method="build_prompt")]

    def _to_records(self, data) -> list:
        if data is None:
            return []
        if hasattr(data, "to_dict"):
            try:
                return data.to_dict(orient="records")
            except Exception:  # noqa: BLE001
                pass
        if isinstance(data, list):
            return [getattr(x, "data", x) for x in data]
        inner = getattr(data, "data", None)
        if isinstance(inner, list):
            return [getattr(x, "data", x) for x in inner]
        if isinstance(inner, dict):
            return [inner]
        return []

    @staticmethod
    def _as_text(value) -> str:
        if value is None:
            return ""
        if isinstance(value, str):
            return value.strip()
        return (getattr(value, "text", "") or "").strip()

    def _focus(self) -> set:
        tickers = set()
        for part in self._as_text(self.focus_tickers).replace(",", " ").split():
            if part:
                tickers.add(part.upper())
        for tok in re.findall(r"\b[A-Z]{2,5}\b", self._as_text(self.question)):
            if tok not in self._NOT_TICKERS:
                tickers.add(tok)
        return tickers

    def _keywords(self) -> set:
        words = re.findall(r"[a-zA-Z]{3,}", self._as_text(self.question).lower())
        return {w for w in words if w not in self._STOP_WORDS}

    def _news_row(self, record):
        if not isinstance(record, dict):
            return None
        meta = record.get("metadata") if isinstance(record.get("metadata"), dict) else record
        body = (
            meta.get("key_observations")
            or meta.get("description")
            or record.get("page_content")
            or ""
        )
        return {
            "ticker": str(meta.get("ticker") or meta.get("ticket") or "?").upper(),
            "title": meta.get("title") or "(untitled)",
            "source": meta.get("source") or "unknown source",
            "date": str(meta.get("publication_date") or "n/a"),
            "url": str(meta.get("url") or "").strip(),
            "sentiment": meta.get("sentiment") or "Neutral",
            "importance": str(meta.get("importance") or "Medium"),
            "body": body.strip() if isinstance(body, str) else "",
        }

    def _news_rows(self) -> list:
        rows = [r for r in (self._news_row(rec) for rec in self._to_records(self.context)) if r]
        if not rows:
            return []
        focus = self._focus()
        words = self._keywords()
        # Keep an article if it is tagged with a focus ticker OR it actually
        # mentions a subject/keyword from the question. This surfaces relevant
        # news even when it is filed under a different ticker (e.g. a market
        # round-up that discusses several names), instead of hard-dropping it.
        if focus or words:
            def relevant(r):
                hay = f"{r['ticker']} {r['title']} {r['source']} {r['body']}".lower()
                if focus and r["ticker"] in focus:
                    return True
                return any(w in hay for w in words)

            rows = [r for r in rows if relevant(r)]
        rows.sort(key=lambda r: r["date"], reverse=True)
        rows.sort(key=lambda r: self._IMPORTANCE.get(r["importance"].lower(), 1))
        return rows[: self.MAX_ARTICLES]

    def _web_rows(self) -> list:
        out = []
        for rec in self._to_records(self.web_results):
            if not isinstance(rec, dict):
                continue
            title = rec.get("title") or rec.get("name") or ""
            url = rec.get("url") or rec.get("link") or rec.get("source") or ""
            content = (
                rec.get("content")
                or rec.get("snippet")
                or rec.get("text")
                or rec.get("page_content")
                or rec.get("answer")
                or ""
            )
            date = rec.get("published_date") or rec.get("date") or ""
            title = str(title).strip()
            content = str(content).strip()
            if not (title or content):
                continue
            out.append(
                {
                    "title": title,
                    "url": str(url).strip(),
                    "content": content,
                    "date": str(date).strip(),
                }
            )
        return out[: self.MAX_WEB]

    def build_prompt(self) -> Message:
        sections: list[str] = []

        live = self._as_text(self.live_data)
        if live:
            sections.append(
                "LIVE MARKET DATA (quote these figures exactly; never alter or invent any):\n" + live
            )

        web = self._web_rows()
        if web:
            blocks = []
            for i, w in enumerate(web, start=1):
                block = f"{i}. {w['title']}".rstrip()
                meta = ", ".join(x for x in (w["url"], w["date"]) if x)
                if meta:
                    block += f"\n   ({meta})"
                if w["content"]:
                    block += "\n   " + w["content"][:400]
                blocks.append(block)
            sections.append(
                "WEB CONTEXT (fresh search results; treat as the current truth, cite the source and date, ignore anything off topic):\n"
                + "\n".join(blocks)
            )

        rows = self._news_rows()
        if rows:
            blocks = []
            for i, r in enumerate(rows, start=1):
                block = (
                    f"{i}. [{r['ticker']}] {r['title']}\n"
                    f"   {r['source']}, {r['date']}, sentiment: {r['sentiment']}, importance: {r['importance']}"
                )
                if r["url"]:
                    block += "\n   " + r["url"]
                if r["body"]:
                    block += "\n   " + r["body"]
                blocks.append(block)
            sections.append(
                "BACKGROUND NEWS you may draw on (cite only what is relevant; never mention this list, its size or its absence):\n"
                + "\n".join(blocks)
            )

        convo = self._as_text(self.history)
        if convo:
            sections.append(
                "EARLIER CONVERSATION (resolve any follow-up reference against this thread):\n" + convo
            )

        question = self._as_text(self.question) or "Give me a brief, concrete read on the market right now."
        sections.append("QUESTION:\n" + question)

        self.status = f"web={len(web)} news={len(rows)} live={'yes' if live else 'no'}"
        return Message(text="\n\n".join(sections))
